import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import { hasNonFoodKeywords, countMatchingFoodKeywords } from "./keywords";

const PEXELS_API = "https://api.pexels.com/v1/search";

interface PexelsImage {
  id: number;
  src: {
    original: string;
    large: string;
    medium: string;
    small: string;
  };
  width: number;
  height: number;
  alt: string;
  tags?: { title: string }[];
}

export async function searchPexelsImages(
  query: string,
  limit: number = 5,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const apiKey = process.env.PEXELS_API_KEY;
    if (!apiKey) return [];

    const params = new URLSearchParams({
      query: `${query} food dish`,
      per_page: String(Math.min(limit * 2, 20)),
      orientation: "landscape",
    });

    const res = await fetch(`${PEXELS_API}?${params}`, {
      headers: {
        Authorization: apiKey,
      },
      signal,
    });

    if (!res.ok) {
      logger.warn(`[Pexels] HTTP ${res.status} for "${query}"`);
      return [];
    }

    const data = await res.json();
    const results: PexelsImage[] = data.photos || [];

    if (results.length === 0) {
      logger.info(`[Pexels] No results for "${query}"`);
      return [];
    }

    const filtered = results.filter((img) => {
      const title = (img.alt || "").toLowerCase();
      const tags = (img.tags || [])
        .map((t) => t.title.toLowerCase())
        .join(" ");

      const combined = `${title} ${tags}`.trim();
      if (combined.length < 5) return false;

      if (countMatchingFoodKeywords(combined, query) < 1) return false;

      if (hasNonFoodKeywords(combined)) return false;

      return true;
    });

    const imageResults: ImageSearchResult[] = filtered
      .slice(0, limit)
      .map((img, index) => ({
        url: img.src.large,
        thumbnail_url: img.src.medium,
        title: img.alt || `${query} photo ${index + 1}`,
        source: "pexels" as const,
        width: img.width,
        height: img.height,
        score: 0,
      }));

    logger.info(`[Pexels] "${query}" returned ${imageResults.length} images`);
    return imageResults;
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      logger.info(`[Pexels] Aborted for "${query}"`);
    } else {
      logger.warn({ message: `[Pexels] Error for "${query}":`, error: typeof error === "string" ? error : error instanceof Error ? error.message : String(error) });
    }
    return [];
  }
}
