import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import { hasNonFoodKeywords, countMatchingFoodKeywords } from "./keywords";

const UNSPLASH_API = "https://api.unsplash.com/search/photos";

interface UnsplashImage {
  id: string;
  urls: {
    regular: string;
    small: string;
    full: string;
  };
  width: number;
  height: number;
  alt_description: string | null;
  description: string | null;
  tags?: { title: string }[];
}

export async function searchUnsplashImages(
  query: string,
  limit: number = 5,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const accessKey = process.env.UNSPLASH_ACCESS_KEY;
    if (!accessKey) return [];

    const params = new URLSearchParams({
      query: `${query} food dish`,
      per_page: String(Math.min(limit * 2, 20)),
      orientation: "landscape",
    });

    const res = await fetch(`${UNSPLASH_API}?${params}`, {
      headers: {
        Authorization: `Client-ID ${accessKey}`,
      },
      signal,
    });

    if (!res.ok) {
      logger.warn(`[Unsplash] HTTP ${res.status} for "${query}"`);
      return [];
    }

    const data = await res.json();
    const results: UnsplashImage[] = data.results || [];

    if (results.length === 0) {
      logger.info(`[Unsplash] No results for "${query}"`);
      return [];
    }

    const filtered = results.filter((img) => {
      const title = (img.alt_description || img.description || "").toLowerCase();
      const tags = (img.tags || [])
        .map((t) => t.title.toLowerCase())
        .join(" ");

      const combined = `${title} ${tags}`.trim();
      if (combined.length < 5) return false;

      if (countMatchingFoodKeywords(combined, query) < 1) return false;

      if (hasNonFoodKeywords(combined)) return false;

      return true;
    });

    const imageResults: ImageSearchResult[] = filtered
      .slice(0, limit)
      .map((img, index) => ({
        url: img.urls.regular,
        thumbnail_url: img.urls.small,
        title: img.alt_description || img.description || `${query} photo ${index + 1}`,
        source: "unsplash" as const,
        width: img.width,
        height: img.height,
        score: 0,
      }));

    logger.info(`[Unsplash] "${query}" returned ${imageResults.length} images`);
    return imageResults;
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      logger.info(`[Unsplash] Aborted for "${query}"`);
    } else {
      logger.warn({ message: `[Unsplash] Error for "${query}":`, error: typeof error === "string" ? error : error instanceof Error ? error.message : String(error) });
    }
    return [];
  }
}
