import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import { hasNonFoodKeywords, countMatchingFoodKeywords } from "./keywords";

const OPENVERSE_API = "https://api.openverse.org/v1/images/";
const UA = "MenuLens/1.0 (https://github.com/menu-lens; menulens@example.com)";

interface OpenverseImage {
  id: string;
  title: string;
  url: string;
  thumbnail: string;
  width: number;
  height: number;
  source: string;
}

interface OpenverseResponse {
  result_count: number;
  results: OpenverseImage[];
}

export async function searchOpenverseImages(
  dishName: string,
  limit: number = 5,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const params = new URLSearchParams({
      q: `${dishName} food dish`,
      page_size: String(Math.min(limit * 3, 20)),
      page: "1",
    });

    const res = await fetch(`${OPENVERSE_API}?${params}`, {
      headers: {
        "User-Agent": UA,
        Accept: "application/json",
      },
      signal,
    });

    if (!res.ok) {
      logger.warn(`[Openverse] HTTP ${res.status} for "${dishName}"`);
      return [];
    }

    const data: OpenverseResponse = await res.json();

    if (!data.results || data.results.length === 0) {
      logger.info(`[Openverse] No results for "${dishName}"`);
      return [];
    }

    const results: ImageSearchResult[] = [];

    for (const img of data.results) {
      if (!img.url || !img.url.startsWith("http")) continue;
      if (!img.thumbnail) continue;

      const title = img.title || "";
      if (!title || title.length < 3) continue;

      const titleLower = title.toLowerCase();

      if (hasNonFoodKeywords(titleLower)) continue;

      if (countMatchingFoodKeywords(titleLower, dishName) < 1) continue;

      results.push({
        url: img.url,
        thumbnail_url: img.thumbnail,
        title: title.slice(0, 120),
        source: "openverse" as const,
        width: img.width || undefined,
        height: img.height || undefined,
        score: 0,
      });

      if (results.length >= limit) break;
    }

    return results;
  } catch {
    logger.warn(`[Openverse] Error for "${dishName}"`);
    return [];
  }
}
