export function hasNonFoodKeywords(text: string): boolean {
  const lower = text.toLowerCase();
  for (const kw of NON_FOOD_KEYWORDS) {
    if (lower.includes(kw)) return true;
  }
  return false;
}

export function hasFoodKeywords(text: string): boolean {
  const lower = text.toLowerCase();
  for (const kw of FOOD_KEYWORDS) {
    if (lower.includes(kw)) return true;
  }
  return false;
}

export function countMatchingFoodKeywords(text: string, query: string): number {
  const lower = text.toLowerCase();
  const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 2);
  let count = 0;
  for (const word of queryWords) {
    if (lower.includes(word)) count++;
  }
  return count;
}

