function simpleHash(str: string): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash);
}

function findCategory(dishName: string): string {
  const lower = dishName.toLowerCase();

  const entries = Object.entries(FOOD_DATABASE);
  for (const [category, data] of entries) {
    if (category === "default") continue;
    if (data.keywords.some((kw) => lower.includes(kw))) {
      return category;
    }
  }

  const words = lower.split(/\s+/);
  for (const word of words) {
    for (const [category, data] of entries) {
      if (category === "default") continue;
      if (data.keywords.some((kw) => kw === word)) {
        return category;
      }
    }
  }

  return "default";
}

export function searchLocalFoodDB(
  dishName: string,
  limit: number = 3
): ImageSearchResult[] {
  const category = findCategory(dishName);
  const foodData = FOOD_DATABASE[category];
  const hash = simpleHash(dishName);
  const offset = hash % foodData.images.length;

  return Array.from({ length: Math.min(limit, foodData.images.length) }, (_, i) => {
    const imgIndex = (offset + i) % foodData.images.length;
    const img = foodData.images[imgIndex];
    return {
      url: img.url,
      thumbnail_url: img.url,
      title: img.title,
      source: "local" as const,
      width: 400,
      height: 300,
      score: 80 - i * 10,
    };
  });
}

export function getLocalCategories(): string[] {
  return Object.keys(FOOD_DATABASE).filter((k) => k !== "default");
}
