import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import { NON_FOOD_ARTICLES, NON_FOOD_SUFFIXES, FOOD_KEYWORDS } from "./keywords";

const WIKI_SEARCH_URL = "https://en.wikipedia.org/w/api.php";
const WIKI_SUMMARY_URL = "https://en.wikipedia.org/api/rest_v1/page/summary";

interface WikiSearchResult {
  title: string;
}

interface WikiSummary {
  thumbnail?: { source: string; width: number; height: number };
  originalimage?: { source: string; width: number; height: number };
  title: string;
  description?: string;
}

function isNonFoodArticle(title: string): boolean {
  const titleLower = title.toLowerCase().trim();
  if (NON_FOOD_ARTICLES.has(titleLower)) return true;

  for (const suffix of NON_FOOD_SUFFIXES) {
    if (titleLower.endsWith(suffix.toLowerCase())) return true;
  }

  return false;
}

function isFoodRelated(title: string, query: string): boolean {
  const titleLower = title.toLowerCase();
  const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 2);

  let matchCount = 0;
  for (const word of queryWords) {
    if (titleLower.includes(word)) matchCount++;
  }

  if (matchCount >= 2) return true;

  if (matchCount === 1) {
    const matchedWord = queryWords.find((w) => titleLower.includes(w));
    if (matchedWord && FOOD_KEYWORDS.has(matchedWord)) return true;
  }

  const titleWords = titleLower.split(/\s+/);
  for (const word of titleWords) {
    if (FOOD_KEYWORDS.has(word) && queryWords.some((qw) => qw === word)) {
      return true;
    }
  }

  return false;
}

async function searchWikipedia(query: string, signal?: AbortSignal): Promise<string[]> {
  try {
    const queryLower = query.toLowerCase();
    const queryWords = queryLower.split(/\s+/).filter((w) => w.length > 2);

    const hasFoodTerm = queryWords.some((w) => FOOD_KEYWORDS.has(w));
    const searchQuery =
      query + (hasFoodTerm || queryWords.length >= 3 ? "" : " food dish");

    const params = new URLSearchParams({
      action: "query",
      list: "search",
      srsearch: searchQuery,
      srlimit: "5",
      format: "json",
      origin: "*",
    });

    const res = await fetch(`${WIKI_SEARCH_URL}?${params}`, {
      headers: { "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)" },
      signal,
    });

    if (!res.ok) return [];

    const data = await res.json();
    const results: WikiSearchResult[] = data.query?.search ?? [];

    const matches: string[] = [];

    for (const result of results) {
      const titleLower = result.title.toLowerCase();
      const queryLower = query.toLowerCase();

      if (isNonFoodArticle(result.title)) continue;

      if (titleLower === queryLower) {
        matches.unshift(result.title);
        continue;
      }

      const queryWords = queryLower.split(/\s+/).filter((w) => w.length > 2);
      const matchCount = queryWords.filter((w) => titleLower.includes(w)).length;

      if (matchCount >= 2) {
        matches.push(result.title);
      } else if (matchCount === 1 && isFoodRelated(result.title, query)) {
        matches.push(result.title);
      }
    }

    return matches;
  } catch {
    return [];
  }
}

async function fetchWikiSummary(
  articleTitle: string,
  signal?: AbortSignal
): Promise<WikiSummary | null> {
  try {
    const res = await fetch(
      `${WIKI_SUMMARY_URL}/${encodeURIComponent(articleTitle)}`,
      {
        headers: { "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)" },
        signal,
      }
    );

    if (!res.ok) return null;

    const data: WikiSummary = await res.json();
    return data;
  } catch {
    return null;
  }
}

function scoreWikiImage(summary: WikiSummary, query: string): number {
  let score = 0;
  const titleLower = (summary.title || "").toLowerCase();
  const queryLower = query.toLowerCase();

  if (titleLower === queryLower) {
    score += 100;
  } else if (titleLower.includes(queryLower)) {
    score += 70;
  }

  const img = summary.originalimage || summary.thumbnail;
  if (!img) return 0;

  if (img.width && img.height && img.width > 400 && img.height > 400) {
    score += 20;
  } else if (img.width && img.height && img.width > 200 && img.height > 200) {
    score += 10;
  }

  if (summary.description && summary.description.length > 50) {
    score += 5;
  }

  return score;
}

export async function searchWikipediaImage(
  query: string,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const articleTitles = await searchWikipedia(query, signal);
    if (articleTitles.length === 0) {
      logger.info(`[Wikipedia] No article found for "${query}"`);
      return [];
    }

    const summaries = await Promise.all(
      articleTitles.map((title) => fetchWikiSummary(title, signal))
    );

    const validResults: ImageSearchResult[] = [];

    for (let i = 0; i < summaries.length; i++) {
      const data = summaries[i];
      if (!data) continue;

      const img = data.originalimage || data.thumbnail;
      if (!img) continue;

      if (img.width && img.height && (img.width < 100 || img.height < 100)) {
        continue;
      }

      const score = scoreWikiImage(data, query);
      if (score === 0) continue;

      validResults.push({
        url: img.source,
        thumbnail_url: img.source,
        title: data.title,
        source: "wikipedia" as const,
        width: img.width,
        height: img.height,
        score,
      });
    }

    validResults.sort((a, b) => b.score - a.score);

    return validResults.slice(0, 1);
  } catch {
    logger.warn(`[Wikipedia] Error fetching image for "${query}"`);
    return [];
  }
}
