import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";

const POLLINATIONS_API = "https://image.pollinations.ai/prompt";

interface PollinationsOptions {
  width?: number;
  height?: number;
  model?: string;
  seed?: number;
}

export async function generateWithPollinations(
  dishName: string,
  options: PollinationsOptions = {},
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const { width = 800, height = 600, model = "flux", seed } = options;

    const prompt = encodeURIComponent(
      `Professional food photography of ${dishName}, appetizing presentation on a plate, well-lit, restaurant quality, high resolution, shallow depth of field, no text no watermark`
    );

    const params = new URLSearchParams({
      width: String(width),
      height: String(height),
      model: model,
      nologo: "true",
    });

    if (seed !== undefined) {
      params.set("seed", String(seed));
    }

    const imageUrl = `${POLLINATIONS_API}/${prompt}?${params}`;

    const response = await fetch(imageUrl, {
      headers: {
        "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)",
      },
      signal,
    });

    if (!response.ok) {
      if (response.status === 429) {
        logger.warn("[Pollinations] Rate limited (429)");
      } else {
        logger.warn(`[Pollinations] HTTP ${response.status}`);
      }
      return [];
    }

    const contentType = response.headers.get("content-type");
    if (!contentType || !contentType.startsWith("image/")) {
      logger.warn("[Pollinations] Non-image response");
      return [];
    }

    const contentLength = response.headers.get("content-length");
    if (contentLength && parseInt(contentLength, 10) < 1000) {
      logger.warn("[Pollinations] Response too small, likely an error image");
      return [];
    }

    logger.info(`[Pollinations] Generated image for "${dishName}"`);
    return [
      {
        url: imageUrl,
        thumbnail_url: imageUrl,
        title: `${dishName} - AI Generated`,
        source: "pollinations" as const,
        width: width,
        height: height,
        score: 0,
      },
    ];
  } catch {
    logger.warn(`[Pollinations] Error for "${dishName}"`);
    return [];
  }
}


