import { ImageSearchResult, ImageSearchResponse } from "@/types/menu";
import { db } from "@/lib/storage";
import { logger } from "@/lib/logger";
import { searchWikipediaImage } from "./wikipedia";
import { searchWikimediaCommons } from "./wikimedia";
import { generateWithPollinations } from "./pollinations";
import { searchOpenverseImages } from "./openverse";
import { searchMealDBImages } from "./mealdb";
import { searchLocalFoodDB } from "./local-db";
import { searchUnsplashImages } from "./unsplash";
import { searchPexelsImages } from "./pexels";
import { searchPixabayImages } from "./pixabay";
import {
  JUNK_KEYWORDS,
  JUNK_URL_PATTERNS,
  STOCK_DOMAIN_PATTERNS,
  FOOD_SITE_PATTERNS,
} from "./keywords";

const CACHE_TTL = 30 * 24 * 60 * 60 * 1000;
const SOURCE_TIMEOUT = 6000;
const MIN_SCORE_THRESHOLD = 35;

const SOURCE_WEIGHTS: Record<string, number> = {
  unsplash: 40,
  pexels: 35,
  pixabay: 35,
  wikimedia: 35,
  openverse: 15,
  wikipedia: 25,
  mealdb: 10,
  pollinations: 15,
  local: 3,
};

const MAX_CONCURRENT_REQUESTS = 6;

async function withConcurrencyLimit<T>(
  fn: () => Promise<T>,
  semaphore: { running: number; queue: Array<() => void> }
): Promise<T> {
  if (semaphore.running >= MAX_CONCURRENT_REQUESTS) {
    await new Promise<void>((resolve) => {
      semaphore.queue.push(resolve);
    });
  }

  semaphore.running++;
  try {
    return await fn();
  } finally {
    semaphore.running--;
    const next = semaphore.queue.shift();
    if (next) next();
  }
}

export async function withTimeout<T>(
  fn: (signal: AbortSignal) => Promise<T>,
  ms: number,
  fallback: T
): Promise<T> {
  return Promise.race([
    fn(new AbortController().signal).catch(() => fallback),
    new Promise<T>((resolve) => setTimeout(() => resolve(fallback), ms)),
  ]);
}

function countWordOverlap(title: string, query: string): number {
  const titleLower = title.toLowerCase();
  const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 2);

  let count = 0;
  for (const word of queryWords) {
    if (titleLower.includes(word)) count++;
  }
  return count;
}

const SCORING_WEIGHTS = {
  exactTitleMatch: 100,
  titleIncludesQuery: 70,
  highOverlapBase: 60,
  highOverlapPerWord: 10,
  mediumOverlapShortQuery: 45,
  mediumOverlapLongQuery: 35,
  lowOverlapBase: 5,
  lowOverlapLongQueryPenalty: 10,
  largeImageBonus: 15,
  mediumImageBonus: 5,
  wikimediaBonus: 5,
  shortTitlePenaltySmall: 20,
  shortTitlePenaltyMedium: 10,
  genericTitlePenalty: 15,
  nonFoodContextPenalty: 30,
  stockDomainPenalty: 20,
  foodSiteBonus: 10,
} as const;

export function scoreResult(result: ImageSearchResult, dishName: string): number {
  let score = 0;
  const titleLower = (result.title || "").toLowerCase();
  const dishLower = dishName.toLowerCase();
  const queryWords = dishLower.split(/\s+/).filter((w) => w.length > 2);
  const totalWords = queryWords.length;

  if (titleLower === dishLower) {
    score += SCORING_WEIGHTS.exactTitleMatch;
  } else if (titleLower.includes(dishLower)) {
    score += SCORING_WEIGHTS.titleIncludesQuery;
  } else {
    const overlap = countWordOverlap(titleLower, dishName);
    if (overlap >= 3) {
      score += SCORING_WEIGHTS.highOverlapBase + overlap * SCORING_WEIGHTS.highOverlapPerWord;
    } else if (overlap === 2) {
      if (totalWords <= 2) {
        score += SCORING_WEIGHTS.mediumOverlapShortQuery;
      } else {
        score += SCORING_WEIGHTS.mediumOverlapLongQuery;
      }
    } else if (overlap === 1) {
      score += SCORING_WEIGHTS.lowOverlapBase;
      if (totalWords > 2) {
        score -= SCORING_WEIGHTS.lowOverlapLongQueryPenalty;
      }
    }
  }

  if (score === 0) score = -20;

  score += SOURCE_WEIGHTS[result.source] || 10;

  if (result.width && result.height && result.width > 200 && result.height > 200) {
    score += SCORING_WEIGHTS.largeImageBonus;
  } else if (result.width && result.height && result.width > 100 && result.height > 100) {
    score += SCORING_WEIGHTS.mediumImageBonus;
  }

  if (result.url.includes("upload.wikimedia.org")) {
    score += SCORING_WEIGHTS.wikimediaBonus;
  }

  const titleLength = (result.title || "").length;
  if (titleLength < 3) {
    score -= SCORING_WEIGHTS.shortTitlePenaltySmall;
  } else if (titleLength < 8) {
    score -= SCORING_WEIGHTS.shortTitlePenaltyMedium;
  }

  const genericTitles = ["image", "photo", "picture", "img", "untitled", "download", "view"];
  if (genericTitles.some((g) => titleLower === g || titleLower.startsWith(g + " "))) {
    score -= SCORING_WEIGHTS.genericTitlePenalty;
  }

  const nonFoodContext = [
    "farm", "farming", "livestock", "poultry", "breed",
    "species", "wild", "habitat", "pet", "zoo",
    "live", "alive", "baby", "cute", "adorable",
    "costume", "craft", "diy", "decoration", "decor",
    "drawing", "painting", "sketch", "artwork",
    "tattoo", "sticker", "emoji", "wallpaper",
  ];
  for (const ctx of nonFoodContext) {
    if (titleLower.includes(ctx)) {
      score -= SCORING_WEIGHTS.nonFoodContextPenalty;
      break;
    }
  }

  for (const domain of STOCK_DOMAIN_PATTERNS) {
    if (result.url.toLowerCase().includes(domain)) {
      score -= SCORING_WEIGHTS.stockDomainPenalty;
      break;
    }
  }

  for (const site of FOOD_SITE_PATTERNS) {
    if (result.url.toLowerCase().includes(site)) {
      score += SCORING_WEIGHTS.foodSiteBonus;
      break;
    }
  }

  return score;
}

export function deduplicate(results: ImageSearchResult[]): ImageSearchResult[] {
  const seen = new Set<string>();
  return results.filter((r) => {
    const key = r.url.split("?")[0];
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function isSearchEngineResultPage(url: string, title: string): boolean {
  const urlLower = url.toLowerCase();
  const titleLower = title.toLowerCase();

  const serpPatterns = [
    /^(discover|browse|explore|search)\s+(and\s+)?(download|find|get)\s+(free\s+)?(images|photos|pictures)/i,
    /^(free\s+)?(stock\s+)?(photos|images|pictures)/i,
    /^(image|photo)\s+search/i,
    /^home\s*page?$/i,
    /^home$/i,
  ];

  for (const pattern of serpPatterns) {
    if (pattern.test(titleLower)) return true;
  }

  const domainOnlyTitles = ["unsplash", "pexels", "openverse", "bing", "wikipedia", "wikimedia"];
  const titleWords = titleLower.split(/\s+/);
  if (titleWords.length <= 2 && domainOnlyTitles.some(d => titleWords.includes(d))) {
    return true;
  }

  if (urlLower.includes("search") && urlLower.includes("q=")) return true;
  if (urlLower.includes("search/results")) return true;

  return false;
}

export function isValidImageUrl(url: string): boolean {
  const urlLower = url.toLowerCase();
  const imageExtensions = [".jpg", ".jpeg", ".png", ".webp", ".bmp", ".tiff"];
  const hasImageExtension = imageExtensions.some(ext => urlLower.includes(ext));
  const hasImagePath = urlLower.includes("/photo") || urlLower.includes("/image") || urlLower.includes("/img") || urlLower.includes("/photos/");
  const apiDomains = ["image.pollinations.ai", "images.unsplash.com", "images.pexels.com", "upload.wikimedia.org"];
  const isApiDomain = apiDomains.some(d => urlLower.includes(d));
  
  return hasImageExtension || hasImagePath || isApiDomain;
}

export function filterJunk(results: ImageSearchResult[]): ImageSearchResult[] {
  return results.filter((r) => {
    const titleLower = (r.title || "").toLowerCase();
    const urlLower = (r.url || "").toLowerCase();

    if (titleLower.length > 0 && titleLower.length < 3) return false;

    for (const keyword of JUNK_KEYWORDS) {
      if (titleLower.includes(keyword)) return false;
    }

    for (const pattern of JUNK_URL_PATTERNS) {
      if (urlLower.includes(pattern)) return false;
    }

    if (isSearchEngineResultPage(r.url, r.title || "")) return false;

    if (!isValidImageUrl(r.url)) return false;

    return true;
  });
}

export async function searchDishImages(
  dishName: string,
  limit: number = 5
): Promise<ImageSearchResponse> {
  const cacheKey = dishName.toLowerCase().trim();
  const now = Date.now();

  try {
    const cached = await db.findOne<{ results: ImageSearchResult[]; expires_at: string }>("cache", {
      dish_name: cacheKey,
      query: cacheKey,
    });

    if (cached && new Date(cached.expires_at).getTime() > now) {
      return {
        dish_name: dishName,
        images: cached.results.slice(0, limit),
        best_match: cached.results[0] || null,
        cached: true,
      };
    }
  } catch {
    // cache lookup failed, continue with search
  }

  const semaphore = { running: 0, queue: [] as Array<() => void> };

  const tier1Results: ImageSearchResult[] = [];
  const tier1 = await Promise.allSettled([
    withTimeout((s) => searchWikipediaImage(dishName, s), SOURCE_TIMEOUT, []),
    withTimeout((s) => searchMealDBImages(dishName, 3, s), SOURCE_TIMEOUT, []),
    withConcurrencyLimit(
      () => Promise.resolve(searchLocalFoodDB(dishName, limit)),
      semaphore
    ),
  ]);
  tier1.forEach((r) => {
    if (r.status === "fulfilled") tier1Results.push(...r.value);
  });

  logger.info(`[ImageSearch] "${dishName}" tier1 raw=${tier1Results.length}`);

  let filtered = filterJunk(tier1Results);
  filtered = deduplicate(filtered);

  const scored = filtered
    .map((r) => ({ ...r, score: scoreResult(r, dishName) }))
    .filter((r) => r.score >= MIN_SCORE_THRESHOLD)
    .sort((a, b) => b.score - a.score);

  logger.info(`[ImageSearch] "${dishName}" tier1 scored=${scored.length} threshold=${MIN_SCORE_THRESHOLD}`);

  const tier1HighQuality = scored.length >= limit && scored.length > 0 &&
    scored.slice(0, Math.min(limit, scored.length)).reduce((sum, r) => sum + r.score, 0) / Math.min(limit, scored.length) > 80 &&
    scored[0].score > 95;

  if (tier1HighQuality) {
    await saveCache(cacheKey, cacheKey, scored.slice(0, limit));
    return {
      dish_name: dishName,
      images: scored.slice(0, limit),
      best_match: scored[0] || null,
      cached: false,
    };
  }

  const tier2Results: ImageSearchResult[] = [];
  const tier2 = await Promise.allSettled([
    withConcurrencyLimit(
      () => withTimeout((s) => searchUnsplashImages(dishName, 5, s), SOURCE_TIMEOUT, []),
      semaphore
    ),
    withConcurrencyLimit(
      () => withTimeout((s) => searchPexelsImages(dishName, 5, s), SOURCE_TIMEOUT, []),
      semaphore
    ),
    withConcurrencyLimit(
      () => withTimeout((s) => searchPixabayImages(dishName, 5, s), SOURCE_TIMEOUT, []),
      semaphore
    ),
    withConcurrencyLimit(
      () => withTimeout((s) => searchOpenverseImages(dishName, 5, s), SOURCE_TIMEOUT, []),
      semaphore
    ),
    withConcurrencyLimit(
      () => withTimeout((s) => searchWikimediaCommons(dishName, 3, s), SOURCE_TIMEOUT, []),
      semaphore
    ),
  ]);
  tier2.forEach((r) => {
    if (r.status === "fulfilled") tier2Results.push(...r.value);
  });

  logger.info(`[ImageSearch] "${dishName}" tier2 raw=${tier2Results.length}`);

  const combined12 = [...scored, ...tier2Results];
  const filtered2 = filterJunk(combined12);
  const deduped2 = deduplicate(filtered2);
  const scored2 = deduped2
    .map((r) => ({ ...r, score: scoreResult(r, dishName) }))
    .filter((r) => r.score >= MIN_SCORE_THRESHOLD)
    .sort((a, b) => b.score - a.score);

  logger.info(`[ImageSearch] "${dishName}" tier1+2 scored=${scored2.length}`);

  if (scored2.length >= limit) {
    await saveCache(cacheKey, cacheKey, scored2.slice(0, limit));
    return {
      dish_name: dishName,
      images: scored2.slice(0, limit),
      best_match: scored2[0] || null,
      cached: false,
    };
  }

  const tier3Results: ImageSearchResult[] = [];
  const tier3 = await Promise.allSettled([
    withConcurrencyLimit(
      () => withTimeout((s) => generateWithPollinations(dishName, {}, s), 6000, []),
      semaphore
    ),
  ]);
  tier3.forEach((r) => {
    if (r.status === "fulfilled") tier3Results.push(...r.value);
  });

  logger.info(`[ImageSearch] "${dishName}" tier3 raw=${tier3Results.length}`);

  const finalCombined = [...scored2, ...tier3Results];
  const finalFiltered = filterJunk(finalCombined);
  const finalDeduped = deduplicate(finalFiltered);
  const finalScored = finalDeduped
    .map((r) => ({ ...r, score: scoreResult(r, dishName) }))
    .filter((r) => r.score >= MIN_SCORE_THRESHOLD)
    .sort((a, b) => b.score - a.score);

  logger.info(`[ImageSearch] "${dishName}" final scored=${finalScored.length}`);

  if (finalScored.length > 0) {
    await saveCache(cacheKey, cacheKey, finalScored.slice(0, limit));
    return {
      dish_name: dishName,
      images: finalScored.slice(0, limit),
      best_match: finalScored[0] || null,
      cached: false,
    };
  }

  const localResults = await searchLocalFoodDB(dishName, limit);
  logger.info(`[ImageSearch] "${dishName}" falling back to local=${localResults.length}`);
  await saveCache(cacheKey, cacheKey, localResults);
  return {
    dish_name: dishName,
    images: localResults.slice(0, limit),
    best_match: localResults[0] || null,
    cached: false,
  };
}

async function saveCache(dishName: string, query: string, results: ImageSearchResult[]): Promise<void> {
  try {
    const existing = await db.findOne<{ id: string }>("cache", { dish_name: dishName, query });
    if (existing?.id) {
      await db.update("cache", existing.id, {
        results,
        best_url: results[0]?.url || "",
        created_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + CACHE_TTL).toISOString(),
      });
    } else {
      await db.create("cache", {
        dish_name: dishName,
        query,
        results,
        best_url: results[0]?.url || "",
        created_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + CACHE_TTL).toISOString(),
      });
    }
  } catch {
    // ignore cache write errors
  }
}
