import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import { hasNonFoodKeywords } from "./keywords";

const PIXABAY_API = "https://pixabay.com/api";

interface PixabayImage {
  id: number;
  webformatURL: string;
  imageWidth: number;
  imageHeight: number;
  tags: string;
  user: string;
}

export async function searchPixabayImages(
  query: string,
  limit: number = 3,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const apiKey = process.env.PIXABAY_API_KEY;
    if (!apiKey) return [];

    const params = new URLSearchParams({
      key: apiKey,
      q: `${query} food dish`,
      image_type: "photo",
      per_page: String(Math.min(limit * 2, 10)),
      safesearch: "true",
    });

    const res = await fetch(`${PIXABAY_API}/?${params}`, {
      signal,
    });

    if (!res.ok) {
      if (res.status !== 429) {
        logger.warn(`[Pixabay] HTTP ${res.status} for "${query}"`);
      }
      return [];
    }

    const data = await res.json();
    const results: PixabayImage[] = data.hits || [];

    if (results.length === 0) {
      return [];
    }

    const filtered = results.filter((img) => {
      const tags = (img.tags || "").toLowerCase();
      if (tags.length < 3) return false;
      if (hasNonFoodKeywords(tags)) return false;

      // Pixabay tags are comma-separated, check if at least one food-related tag matches
      const queryWords = query.toLowerCase().split(/\s+/).filter(w => w.length > 2);
      const hasMatching = queryWords.some(w => tags.includes(w));
      if (!hasMatching && queryWords.length > 0) return false;

      return true;
    });

    const imageResults: ImageSearchResult[] = filtered
      .slice(0, limit)
      .map((img) => ({
        url: img.webformatURL.replace("_640", "_1280"), // get largest available
        thumbnail_url: img.webformatURL,
        title: img.tags?.split(",")[0]?.trim() || `${query} photo`,
        source: "pixabay" as const,
        width: img.imageWidth,
        height: img.imageHeight,
        score: 0,
      }));

    logger.info(`[Pixabay] "${query}" returned ${imageResults.length} images`);
    return imageResults;
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      return [];
    }
    logger.warn(`[Pixabay] Error for "${query}": ${error instanceof Error ? error.message : String(error)}`);
    return [];
  }
}
