import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";

const BASE_URL = "https://www.themealdb.com/api/json/v1/1";

interface MealDBMeal {
  idMeal: string;
  strMeal: string;
  strMealThumb: string;
  strCategory: string;
  strArea: string;
}

interface MealDBResponse {
  meals: MealDBMeal[] | null;
}

export async function searchMealDBImages(
  dishName: string,
  limit: number = 5,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    let meals: MealDBMeal[] = [];

    const res = await fetch(
      `${BASE_URL}/search.php?s=${encodeURIComponent(dishName)}`,
      {
        headers: {
          "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)",
        },
        signal,
      }
    );

    if (res.ok) {
      const data: MealDBResponse = await res.json();
      meals = data.meals ?? [];
    }

    if (meals.length === 0) {
      const foodWords = [
        "chicken", "beef", "pork", "lamb", "fish", "duck",
        "pizza", "pasta", "noodle", "rice", "bread", "salad", "soup",
        "curry", "tikka", "masala", "biryani", "kebab",
        "sushi", "ramen", "steak", "burger",
        "cake", "pie", "cookie",
        "shrimp", "lobster", "crab", "salmon",
      ];
      const words = dishName
        .split(/\s+/)
        .filter((w) => w.length >= 3)
        .filter((w) => foodWords.includes(w.toLowerCase()));

      if (words.length >= 2) {
        const searchWord = words.slice(0, 2).join(" ");
        const wordRes = await fetch(
          `${BASE_URL}/search.php?s=${encodeURIComponent(searchWord)}`,
          {
            headers: {
              "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)",
            },
            signal,
          }
        );
        if (wordRes.ok) {
          const wordData: MealDBResponse = await wordRes.json();
          if (wordData.meals && wordData.meals.length > 0) {
            meals = wordData.meals;
          }
        }
      }
    }

    const sliced = meals.slice(0, limit).map((meal) => ({
      url: meal.strMealThumb,
      thumbnail_url: meal.strMealThumb,
      title: meal.strMeal,
      source: "mealdb" as const,
      score: 0,
    }));
    logger.info(`[MealDB] "${dishName}" returned ${sliced.length} images`);
    return sliced;
  } catch {
    logger.warn(`[MealDB] Search failed for "${dishName}"`);
    return [];
  }
}
