import { ImageSearchResult } from "@/types/menu";
import { logger } from "@/lib/logger";
import {
  FOOD_KEYWORDS,
  ANIMAL_CONTEXT_WORDS,
  hasNonFoodKeywords,
  countMatchingFoodKeywords,
} from "./keywords";

const COMMONS_API = "https://commons.wikimedia.org/w/api.php";
const ALLOWED_MIMES = new Set(["image/jpeg", "image/png", "image/webp"]);
const UA = "MenuLens/1.0 (https://github.com/menu-lens; menulens@example.com) node.js";

interface WikimediaPage {
  title: string;
  imageinfo?: {
    url: string;
    thumburl?: string;
    mime: string;
    width?: number;
    height?: number;
  }[];
}

interface WikimediaSearchResult {
  title: string;
}

interface WikimediaSearchResponse {
  query?: {
    search?: WikimediaSearchResult[];
  };
}

interface WikimediaImageResponse {
  query?: {
    pages?: Record<string, WikimediaPage>;
  };
}

function isNonFoodImage(title: string): boolean {
  if (hasNonFoodKeywords(title.toLowerCase())) return true;

  const titleLower = title.toLowerCase();
  if (titleLower.startsWith("file:") || titleLower.startsWith("image:")) {
    const baseName = titleLower.replace(/^(file|image):/, "").replace(/\.\w+$/, "");
    if (hasNonFoodKeywords(baseName)) return true;
  }

  return false;
}

function isFoodRelated(title: string, query: string): boolean {
  const titleLower = title.toLowerCase();

  if (ANIMAL_CONTEXT_WORDS.some((w) => titleLower.includes(w))) return false;

  if (countMatchingFoodKeywords(titleLower, query) >= 2) return true;

  const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 2);
  const matchedWord = queryWords.find((w) => titleLower.includes(w));
  if (matchedWord && FOOD_KEYWORDS.has(matchedWord)) return true;

  return false;
}

export async function searchWikimediaCommons(
  query: string,
  limit: number = 5,
  signal?: AbortSignal
): Promise<ImageSearchResult[]> {
  try {
    const searchQuery = `${query} food dish`;
    const params = new URLSearchParams({
      action: "query",
      list: "search",
      srsearch: searchQuery,
      srnamespace: "6",
      srlimit: String(Math.min(limit * 5, 30)),
      format: "json",
      origin: "*",
    });

    const searchRes = await fetch(`${COMMONS_API}?${params}`, {
      headers: { "User-Agent": UA },
      signal,
    });

    if (!searchRes.ok) {
      logger.warn(`Wikimedia Commons search failed: ${searchRes.status}`);
      return [];
    }

    const searchData: WikimediaSearchResponse = await searchRes.json();
    const searchResults: WikimediaSearchResult[] =
      searchData.query?.search ?? [];

    if (searchResults.length === 0) {
      logger.info(`[Wikimedia] No search results for "${query}"`);
      return [];
    }

    const titles = searchResults
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .map((r: any) => r.title)
      .filter((t: string) => !isNonFoodImage(t))
      .slice(0, limit * 2);

    if (titles.length === 0) {
      logger.info(`[Wikimedia] All results filtered as non-food for "${query}"`);
      return [];
    }

    const imageParams = new URLSearchParams({
      action: "query",
      titles: titles.join("|"),
      prop: "imageinfo",
      iiprop: "url|mime|size",
      iiurlwidth: "800",
      format: "json",
      origin: "*",
    });

    const imageRes = await fetch(`${COMMONS_API}?${imageParams}`, {
      headers: { "User-Agent": UA },
      signal,
    });

    if (!imageRes.ok) {
      logger.warn(`Wikimedia Commons image fetch failed: ${imageRes.status}`);
      return [];
    }

    const imageData: WikimediaImageResponse = await imageRes.json();
    const pages: Record<string, WikimediaPage> = imageData.query?.pages ?? {};

    const results: ImageSearchResult[] = [];

    for (const page of Object.values(pages)) {
      const info = page.imageinfo?.[0];
      if (!info || !ALLOWED_MIMES.has(info.mime)) continue;
      if (info.width && info.height && (info.width < 100 || info.height < 100)) continue;

      const title = page.title.replace(/^File:/, "").replace(/\.\w+$/, "");

      if (isNonFoodImage(page.title)) continue;
      if (!isFoodRelated(title, query)) continue;

      results.push({
        url: info.thumburl || info.url,
        thumbnail_url: info.thumburl || info.url,
        title: title,
        source: "wikimedia" as const,
        width: info.width,
        height: info.height,
        score: 0,
      });

      if (results.length >= limit) break;
    }

    logger.info({ message: `[Wikimedia] "${query}" returned ${results.length} images` });
    return results;
  } catch (err) {
    logger.warn({ message: "Wikimedia Commons search failed", error: err instanceof Error ? err.message : String(err) });
    return [];
  }
}
